/**
 * x402 v2 support, client side.
 *
 * A v2 server puts the challenge in a `payment-required` HTTP header rather
 * than the response body — Agent402 answers 402 with a body of literally `{}` —
 * so a v1 parser that only reads the body sees no offer at all and cannot even
 * quote the call.
 *
 * What v2 does NOT change is the cryptography. The `exact` scheme is still an
 * EIP-3009 `TransferWithAuthorization` signed over an EIP-712 hash, and a v2
 * Celo offer names the same USDC contract and the same `{name, version}` domain
 * this client already builds. So this module normalises v2 into the v1 shape and
 * stops there: signing, keystore access, nonce generation and validity windows
 * are shared, untouched, and must stay that way.
 *
 * Two things differ on the wire besides the location, and both are handled here
 * rather than leaking downstream:
 *
 *   - the network is a CAIP-2 id (`eip155:42220`) instead of a slug (`celo`)
 *   - the amount field is `amount` instead of `maxAmountRequired`
 *
 * and one differs on the way back out, handled by the caller:
 *
 *   - payment goes in `PAYMENT-SIGNATURE`, not `X-PAYMENT`
 */
import type { PaymentRequiredEnvelope } from './types.js';
/** The header a v2 server puts its challenge in. */
export declare const V2_CHALLENGE_HEADER = "payment-required";
/** The header a v2 client puts its signed payment in. */
export declare const V2_PAYMENT_HEADER = "PAYMENT-SIGNATURE";
/**
 * CAIP-2 id for a network slug — the inverse of {@link networkFromCaip2}.
 *
 * Needed because the payment payload has to echo the network in the SAME form
 * the server advertised. A v2 server matches the payload's `network` against
 * its own offers and rejects `"celo"` outright:
 *
 *   {"error":"Payment rejected","reason":"unsupported-network",
 *    "hint":"Network \"celo\" is not offered on this route. Offered: … eip155:42220 …"}
 *
 * Learned from a live call, not from the spec — the spec fixes the payload's
 * SHAPE and says nothing about which spelling of the network survives the round
 * trip. `network` is not part of the EIP-3009 signed struct, so re-spelling it
 * does not touch the signature.
 */
export declare function caip2FromNetwork(slug: string): string | undefined;
/** Network slug for a CAIP-2 id, or undefined if this client will not act on it. */
export declare function networkFromCaip2(id: string): string | undefined;
/**
 * Decode a `payment-required` header into the v1 envelope shape.
 *
 * `resource` is the URL that was requested: v2 offers do not carry it, but the
 * v1 shape and everything reading it do.
 *
 * Returns undefined if the header is absent, undecodable, not a v2 challenge,
 * or carries no offer this client can act on — the same fail-closed contract
 * `parseEnvelope` has for an unparseable body.
 */
export declare function parseV2Header(headerValue: string | null | undefined, resource: string): PaymentRequiredEnvelope | undefined;
